"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type KeyboardEvent, type RefObject } from "react";

import { IconChevronDown, IconChevronUp, IconClose, IconSearch } from "@rhs-ui/icons";
import {
  addHighlightStyles,
  BlockStore,
  buildPattern,
  canHighlight,
  DEFAULT_LABELS,
  fill,
  findAll,
  findFrom,
  MAX_MARKED,
  scrollIntoMargin,
  unwrap,
  wrap,
  type Anchor,
  type FindLabels,
  type FindMatches,
  type FindOptions,
  type FoundMatch,
  type Wrapped,
} from "@rhs-ui/application/find-in-page-bar/search";
import { Button } from "@rhs-ui/primitives/button";
import { Toggle } from "@rhs-ui/primitives/toggle";
import { cn } from "@/lib/utils";

export type { FindLabels, FindMatches, FindOptions } from "@rhs-ui/application/find-in-page-bar/search";

export interface FindInPageBarProps extends Omit<ComponentProps<"div">, "children" | "onChange"> {
  /** The region to search: the article, the log, the document. Its text is read, never changed (the wrapper marks are taken out again). Make it focusable, or leave it to the bar: with the shortcut on it gets `tabindex="-1"` so a click inside puts keyboard focus there. */
  containerRef: RefObject<HTMLElement | null>;
  /** Whether the bar is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when the bar opens (the shortcut, or you) or closes (Escape, the close button). Closing takes the marks off the text and gives focus back to where it was. */
  onOpenChange?: (open: boolean) => void;
  /** What the field starts with, which is searched at once. */
  defaultQuery?: string;
  /** Upper case is not lower case: the state of the "Aa" button, when you control it. Pass `onOptionsChange` with it. */
  caseSensitive?: boolean;
  /** `cat` is not found in `category`: the state of the whole word button, when you control it. Pass `onOptionsChange` with it. */
  wholeWord?: boolean;
  /** Called with both options each time one of the two buttons is pressed. */
  onOptionsChange?: (options: FindOptions) => void;
  /** Open on Ctrl or Cmd with F while focus is inside the region, so the browser's own find still works everywhere else. Default true. */
  shortcut?: boolean;
  /** How matches are marked: "auto" uses the CSS Custom Highlight API where the browser has it, which leaves the page's elements alone, and wrapper marks where it does not; "marks" always wraps. Default "auto". */
  highlight?: "auto" | "marks";
  /** Called when the search has settled and each time the current match changes, with the query, how many matches there are and which one is current. */
  onMatchesChange?: (matches: FindMatches) => void;
  /** The language the counts are written in. Default "en-US". */
  locale?: string;
  /** The words the bar says, for translation. */
  labels?: FindLabels;
}

/** A Ctrl or Cmd with F, and no other modifier. */
const isFindKey = (event: { key: string; ctrlKey: boolean; metaKey: boolean; altKey: boolean; shiftKey: boolean }) =>
  (event.ctrlKey || event.metaKey) && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "f";

/** In marks mode the marks move with the current match once it comes this close to the edge of the ones that are marked. */
const EDGE = 40;

/**
 * Find text inside a document, a log or an article. A small bar anchored to the top right of a region, with the count
 * ("3 of 12", said in a polite live region, "No results" when empty), next and previous, and the matches marked in the text:
 * with the CSS Custom Highlight API where the browser has it, and with wrapper marks where it does not. The current match is
 * marked more strongly and scrolled into view with room around it. Enter and Shift with Enter step through the matches, Escape closes
 * the bar and takes the marks off, and the case and whole-word options are real pressed buttons. A large document is searched in
 * idle slices, so typing never stalls; with wrapper marks, which are real changes to the page, about 500 matches around the current
 * one are marked at a time and the marks move along as it does, while the count always covers them all. Put the bar inside a
 * `relative` wrapper around the region, not inside the element that scrolls, so it stays put as the text moves, and leave room at the
 * top of the region as high as the bar (two rows on a phone) so the first lines are not under it. A bar that is open from the start
 * (`defaultOpen`, or `open` true on the first render) does not take focus or move the page: that is only for a bar somebody opened.
 */
export function FindInPageBar({
  containerRef,
  open,
  defaultOpen = false,
  onOpenChange,
  defaultQuery = "",
  caseSensitive,
  wholeWord,
  onOptionsChange,
  shortcut = true,
  highlight = "auto",
  onMatchesChange,
  locale = "en-US",
  labels,
  className,
  ...props
}: FindInPageBarProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const id = useId().replace(/[^a-zA-Z0-9]/g, "");
  const names = { all: `rhs-find-${id}`, current: `rhs-find-${id}-current` };
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  const [mounted, setMounted] = useState(isOpen);
  // A bar that is open from the start (a preview, a log with its query ready) leaves the page alone: it takes no focus and scrolls nothing
  // until somebody uses it. Closing it ends that, so a bar that is opened later behaves as one that was asked for.
  const calm = useRef(isOpen);
  const [query, setQuery] = useState(defaultQuery);
  const [ownCase, setOwnCase] = useState(false);
  const [ownWord, setOwnWord] = useState(false);
  const [total, setTotal] = useState(0);
  const [current, setCurrent] = useState(-1);
  const [searching, setSearching] = useState(false);
  const [capped, setCapped] = useState(false);
  const [version, setVersion] = useState(0);
  const [said, setSaid] = useState("");
  const bar = useRef<HTMLDivElement>(null);
  const field = useRef<HTMLInputElement>(null);
  const matches = useRef<FoundMatch[]>([]);
  const at = useRef(-1);
  const token = useRef(0);
  const store = useRef<BlockStore | null>(null);
  const anchor = useRef<Anchor | null>(null);
  const wrapped = useRef<Wrapped | null>(null);
  /** Which matches are wrapped in marks right now: from the first, up to (not including) the last. */
  const painted = useRef<{ from: number; to: number } | null>(null);
  /** Whether this search marks with wrapper marks, which have no ranges and cover a window of the matches. */
  const marking = useRef(false);
  const observer = useRef<MutationObserver | null>(null);
  const returnTo = useRef<HTMLElement | null>(null);
  const matchCase = caseSensitive ?? ownCase;
  const whole = wholeWord ?? ownWord;
  const number = (value: number) => new Intl.NumberFormat(locale).format(value);

  function setOpen(next: boolean) {
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  /** Runs a change to the region's own text without the observer taking it for somebody else's. */
  function quietly(change: () => void) {
    change();
    observer.current?.takeRecords();
  }

  function clearPaint() {
    const marks = wrapped.current;
    if (marks) quietly(() => unwrap(marks));
    wrapped.current = null;
    painted.current = null;
    if (canHighlight()) {
      CSS.highlights.delete(names.all);
      CSS.highlights.delete(names.current);
    }
  }

  /** Marks the matches around one of them (about 500) with wrapper marks, and takes the marks off the ones that were marked before. */
  function paintAround(index: number) {
    const list = matches.current;
    const start = Math.max(0, Math.min(index - MAX_MARKED / 2, list.length - MAX_MARKED));
    const end = Math.min(list.length, start + MAX_MARKED);
    quietly(() => {
      if (wrapped.current) unwrap(wrapped.current);
      wrapped.current = wrap(list, start, end);
    });
    painted.current = { from: start, to: end };
  }

  /** Makes a match the current one: marks it more strongly, remembers where it is, and brings it into view. */
  function showCurrent(index: number, scroll: boolean) {
    const match = matches.current[index];
    const head = match?.pieces[0];
    if (!match || !head) return;
    if (marking.current) {
      // Only the matches around the current one wear marks: when it comes near the edge of them, they move along with it.
      const span = painted.current;
      const lead = span && span.from > 0 ? EDGE : 0;
      const trail = span && span.to < matches.current.length ? EDGE : 0;
      if (!span || index < span.from + lead || index >= span.to - trail) paintAround(index);
      const marks = wrapped.current?.marks;
      marks?.get(at.current)?.forEach((mark) => mark.removeAttribute("data-current"));
      marks?.get(index)?.forEach((mark) => mark.setAttribute("data-current", ""));
    } else if (canHighlight() && match.range) {
      const strong = new Highlight(match.range);
      strong.priority = 1;
      CSS.highlights.set(names.current, strong);
    }
    at.current = index;
    anchor.current = { node: head.node, offset: head.from };
    setCurrent(index);
    // The room left around the match is at least the height of the bar and a little more, so it is never under it: on a phone the bar is two rows.
    const target = marking.current ? wrapped.current?.marks.get(index)?.[0] : match.range;
    if (scroll && target) scrollIntoMargin(() => target.getBoundingClientRect(), head.node.parentElement, Math.max(80, (bar.current?.offsetHeight ?? 0) + 28));
  }

  function step(delta: number) {
    const size = matches.current.length;
    if (size) showCurrent((at.current + delta + size) % size, true);
  }

  function close() {
    const back = returnTo.current;
    const inside = bar.current?.contains(document.activeElement);
    setOpen(false);
    returnTo.current = null;
    // Focus goes back to where it was when the bar opened, but only if it was the bar that had it.
    if (inside) window.requestAnimationFrame(() => (back?.isConnected ? back : containerRef.current)?.focus({ preventScroll: true }));
  }

  // The bar leaves a moment after it is told to, so it can fade.
  useEffect(() => {
    if (isOpen) {
      setMounted(true);
      return;
    }
    if (!mounted) return;
    const timer = window.setTimeout(() => setMounted(false), 200);
    return () => window.clearTimeout(timer);
  }, [isOpen, mounted]);

  // Once the bar has been closed it is no longer the bar that was there from the start.
  useEffect(() => {
    if (!isOpen) calm.current = false;
  }, [isOpen]);

  // The field takes focus and what is in it is selected, so typing replaces it; where focus was is kept for the way out. A bar that was
  // there from the start does none of it: it leaves focus where it is until somebody goes to the field.
  useEffect(() => {
    if (!isOpen || !mounted || calm.current) return;
    const active = document.activeElement;
    if (active instanceof HTMLElement && active !== document.body && !bar.current?.contains(active)) returnTo.current = active;
    field.current?.focus({ preventScroll: true });
    field.current?.select();
  }, [isOpen, mounted]);

  // The shortcut belongs to the region: it works while focus is inside it, and the browser's find works everywhere else.
  useEffect(() => {
    const root = containerRef.current;
    if (!shortcut || !root) return;
    const listener = (event: globalThis.KeyboardEvent) => {
      if (!isFindKey(event)) return;
      event.preventDefault();
      if (isOpen) {
        field.current?.focus({ preventScroll: true });
        field.current?.select();
      } else setOpen(true);
    };
    root.addEventListener("keydown", listener);
    // A click on text puts focus on the nearest focusable element; this makes the region itself one, so there is somewhere for the key to land.
    const made = !root.hasAttribute("tabindex");
    if (made) root.tabIndex = -1;
    return () => {
      root.removeEventListener("keydown", listener);
      if (made) root.removeAttribute("tabindex");
    };
  }, [shortcut, isOpen, containerRef]); // eslint-disable-line react-hooks/exhaustive-deps

  // The rules that paint the highlights, for as long as the bar is open.
  useEffect(() => {
    if (!isOpen || highlight === "marks" || !canHighlight()) return;
    return addHighlightStyles(names.all, names.current);
  }, [isOpen, highlight, names.all, names.current]); // eslint-disable-line react-hooks/exhaustive-deps

  // If the text of the region changes under the search (a log that grows, a page that renders more), the search is done again.
  useEffect(() => {
    const root = containerRef.current;
    if (!isOpen || !root || typeof MutationObserver === "undefined") return;
    let timer = 0;
    const watching = new MutationObserver(() => {
      window.clearTimeout(timer);
      timer = window.setTimeout(() => {
        store.current = null;
        setVersion((value) => value + 1);
      }, 250);
    });
    watching.observe(root, { childList: true, subtree: true, characterData: true });
    observer.current = watching;
    return () => {
      window.clearTimeout(timer);
      watching.disconnect();
      observer.current = null;
    };
  }, [isOpen, containerRef]);

  // The search itself: on every change of what is asked, in slices, marking as it goes.
  useEffect(() => {
    const root = containerRef.current;
    const mine = (token.current += 1);
    const stale = () => token.current !== mine;
    clearPaint();
    matches.current = [];
    at.current = -1;
    const pattern = isOpen && mounted && root ? buildPattern(query, { caseSensitive: matchCase, wholeWord: whole }) : null;
    // A bar that is closed holds on to none of the page's text nodes.
    if (!isOpen) store.current = null;
    if (!pattern || !root) {
      setTotal(0);
      setCurrent(-1);
      setCapped(false);
      setSearching(false);
      return;
    }
    const marksMode = highlight === "marks" || !canHighlight();
    marking.current = marksMode;
    setSearching(true);
    setCapped(false);
    store.current ??= new BlockStore(root);
    const source = store.current;
    void (async () => {
      const found: FoundMatch[] = [];
      const painting = marksMode ? null : new Highlight();
      if (painting) CSS.highlights.set(names.all, painting);
      let chosen = -1;
      // The page moves only for a search somebody asked for (typing, a key, a button): the one a bar starts with does not scroll anything.
      const scrolls = () => !calm.current;
      // Matches are found without ranges when they are going to be marks: a live range costs every split and move of a node an update.
      for await (const batch of findAll(source, pattern, stale, { ranges: !marksMode })) {
        if (stale()) return;
        for (const match of batch.matches) {
          found.push(match);
          if (painting && match.range) painting.add(match.range);
        }
        matches.current = found;
        setTotal(found.length);
        // The match to land on is the first at or after where the last one was, so a growing query does not jump back to the top.
        if (!marksMode && chosen < 0) {
          const place = anchor.current ? findFrom(found, anchor.current) : found.length ? 0 : -1;
          if (place >= 0) {
            chosen = place;
            showCurrent(place, scrolls());
          }
        }
        if (!batch.done) continue;
        // Highlighted matches are painted as they come and already have a current one by now, unless none came after the anchor; wrapper marks go
        // on once, here, around the match that is current.
        if (found.length && (marksMode || chosen < 0)) {
          chosen = marksMode && anchor.current ? Math.max(0, findFrom(found, anchor.current)) : 0;
          showCurrent(chosen, scrolls());
        }
        setCapped(batch.capped);
        setSearching(false);
      }
    })();
    return () => {
      token.current += 1;
    };
  }, [isOpen, mounted, query, matchCase, whole, highlight, version, containerRef]); // eslint-disable-line react-hooks/exhaustive-deps

  // Nothing is left behind when the bar goes: no marks in the text, no highlight in the registry.
  useEffect(
    () => () => {
      token.current += 1;
      clearPaint();
    },
    [], // eslint-disable-line react-hooks/exhaustive-deps
  );

  const asked = query.trim() !== "";
  const count = !asked || (searching && total === 0) ? "" : total === 0 ? words.noResults : fill(words.count, { current: current >= 0 ? number(current + 1) : "…", total: `${number(total)}${searching || capped ? "+" : ""}` });
  const status = !asked || searching ? "" : total === 0 ? words.noResults : fill(words.count, { current: number(Math.max(current, 0) + 1), total: number(total) });

  // The live region is told once the numbers have stopped moving, and not on every key.
  useEffect(() => {
    const timer = window.setTimeout(() => setSaid(status), 350);
    return () => window.clearTimeout(timer);
  }, [status]);

  useEffect(() => {
    if (searching) return;
    onMatchesChange?.({ query, total, current: total === 0 ? 0 : current + 1 });
  }, [searching, total, current, query]); // eslint-disable-line react-hooks/exhaustive-deps

  function keys(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
    } else if (isFindKey(event)) {
      event.preventDefault();
      field.current?.focus();
      field.current?.select();
    }
  }

  if (!mounted) return null;

  const idle = total === 0;
  return (
    <div
      ref={bar}
      role="search"
      aria-label={words.label}
      data-slot="find-in-page-bar"
      data-state={isOpen ? "open" : "closed"}
      onKeyDown={keys}
      className={cn("@container absolute top-3 right-3 z-30 w-[min(28rem,calc(100%-1.5rem))]", className)}
      {...props}
    >
      <div
        className={cn(
          "flex flex-wrap items-center gap-1 rounded-xl border border-border bg-popover p-1.5 text-popover-foreground shadow-sm @md:flex-nowrap",
          "transition-[opacity,transform] duration-150 ease-out starting:-translate-y-1.5 starting:opacity-0 motion-reduce:transition-none",
          !isOpen && "pointer-events-none -translate-y-1.5 opacity-0",
        )}
      >
        <div className="relative order-1 min-w-0 flex-1 basis-[calc(100%-2.25rem)] @md:basis-auto">
          <IconSearch aria-hidden="true" size={16} className="pointer-events-none absolute top-1/2 left-2.5 -translate-y-1/2 text-muted-foreground" />
          <input
            ref={field}
            type="text"
            value={query}
            placeholder={words.find}
            aria-label={words.find}
            autoComplete="off"
            autoCorrect="off"
            autoCapitalize="off"
            spellCheck={false}
            enterKeyHint="search"
            onChange={(event) => {
              calm.current = false;
              setQuery(event.target.value);
            }}
            onKeyDown={(event) => {
              if (event.key !== "Enter") return;
              event.preventDefault();
              step(event.shiftKey ? -1 : 1);
            }}
            className="h-8 w-full min-w-0 rounded-md border border-input bg-background pr-[5.5rem] pl-8 text-sm shadow-xs outline-none transition-[border-color,box-shadow] duration-150 placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none"
          />
          <span aria-hidden="true" className={cn("pointer-events-none absolute top-1/2 right-2.5 -translate-y-1/2 text-xs whitespace-nowrap tabular-nums", asked && !searching && total === 0 ? "font-medium text-foreground" : "text-muted-foreground")}>
            {count}
          </span>
        </div>

        {/* aria-disabled and not disabled: a button that disables itself under the finger would drop keyboard focus to the page. */}
        <Button type="button" variant="ghost" size="icon-sm" aria-label={words.previous} aria-disabled={idle || undefined} onClick={() => step(-1)} className="order-3 aria-disabled:pointer-events-none aria-disabled:opacity-40">
          <IconChevronUp />
        </Button>
        <Button type="button" variant="ghost" size="icon-sm" aria-label={words.next} aria-disabled={idle || undefined} onClick={() => step(1)} className="order-3 aria-disabled:pointer-events-none aria-disabled:opacity-40">
          <IconChevronDown />
        </Button>
        <span aria-hidden="true" className="order-3 mx-0.5 h-5 w-px bg-border" />
        <Toggle
          size="sm"
          aria-label={words.matchCase}
          pressed={matchCase}
          onPressedChange={(next) => {
            calm.current = false;
            if (caseSensitive === undefined) setOwnCase(next);
            onOptionsChange?.({ caseSensitive: next, wholeWord: whole });
          }}
          className="order-3 px-0 text-[0.8125rem] font-semibold"
        >
          {/* The glyph is drawn by the style, not written in the markup, so the button's name (Match case) is the only text it has and a voice control says that. */}
          <span aria-hidden="true" className="before:content-['Aa']" />
        </Toggle>
        <Toggle
          size="sm"
          aria-label={words.wholeWord}
          pressed={whole}
          onPressedChange={(next) => {
            calm.current = false;
            if (wholeWord === undefined) setOwnWord(next);
            onOptionsChange?.({ caseSensitive: matchCase, wholeWord: next });
          }}
          className="order-3 px-0"
        >
          <span aria-hidden="true" className="rounded-[3px] border border-current px-1 text-[0.6875rem] leading-4 font-semibold before:content-['ab']" />
        </Toggle>
        <Button type="button" variant="ghost" size="icon-sm" aria-label={words.close} onClick={close} className="order-2 @md:order-4">
          <IconClose />
        </Button>
        <span role="status" aria-live="polite" className="sr-only">
          {said}
        </span>
      </div>
    </div>
  );
}

/**
 * The engine of the find bar, as plain functions with no state and no hook: it reads the text of a region, finds a query in
 * it in slices so a big document never stalls typing, and marks what it found either with the CSS Custom Highlight API or, where
 * the browser has none, by wrapping the matches in `<mark>`. A Server Component can import the words and the types from here.
 */

/** The options of a search. */
export interface FindOptions {
  /** `A` is not `a`. */
  caseSensitive: boolean;
  /** `cat` is not found inside `category`. */
  wholeWord: boolean;
}

/** What `onMatchesChange` receives. */
export interface FindMatches {
  /** What was searched for. */
  query: string;
  /** How many matches there are. The count stops at 10 000. */
  total: number;
  /** The one that is current, from 1 (the "3" of "3 of 12"), or 0 when there is none. */
  current: number;
}

/** The words the bar says, for translation. Use `{current}` and `{total}` where the defaults do. */
export interface FindLabels {
  /** The name of the bar, for screen readers. Default "Find in page". */
  label?: string;
  /** The hint in the field, and its name. Default "Find". */
  find?: string;
  /** The count. Default "{current} of {total}". */
  count?: string;
  /** What is said when the text is nowhere. Default "No results". */
  noResults?: string;
  /** The name of the button that goes to the previous match. Default "Previous match". */
  previous?: string;
  /** The name of the button that goes to the next match. Default "Next match". */
  next?: string;
  /** The name of the button that tells upper case from lower case. Default "Match case". */
  matchCase?: string;
  /** The name of the button that finds whole words only. Default "Whole word". */
  wholeWord?: string;
  /** The name of the button that closes the bar. Default "Close". */
  close?: string;
}

export const DEFAULT_LABELS = {
  label: "Find in page",
  find: "Find",
  count: "{current} of {total}",
  noResults: "No results",
  previous: "Previous match",
  next: "Next match",
  matchCase: "Match case",
  wholeWord: "Whole word",
  close: "Close",
} satisfies Required<FindLabels>;

/** Puts values into a template: `fill("{current} of {total}", { current: 3, total: 12 })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match));
}

/** No more matches than this are kept: a query that matches everything must not take the page down. */
export const MAX_MATCHES = 10_000;

/** The class of a wrapper mark, for the browsers that cannot paint a range. The current match adds `data-current`. */
export const MARK_CLASS = "rounded-[2px] bg-foreground/20 text-inherit data-[current]:bg-foreground data-[current]:text-background";

/** Elements whose text is never searched: code that is not text, hidden text, and text that is only for screen readers. */
const SKIPPED = "script,style,noscript,template,textarea,select,option,[hidden],[aria-hidden='true'],.sr-only,[data-find-skip],[data-slot='find-in-page-bar']";

/** Elements that end a line of text: a match is never found across two of them. */
const BLOCKS =
  "address,article,aside,blockquote,dd,details,dialog,div,dl,dt,fieldset,figcaption,figure,footer,form,h1,h2,h3,h4,h5,h6,header,hgroup,hr,li,main,nav,ol,p,pre,section,summary,table,tbody,td,tfoot,th,thead,tr,ul";

/** The pattern for a query, or null when there is nothing to look for. The query is text, never a pattern: every character is taken as it is. */
export function buildPattern(query: string, { caseSensitive, wholeWord }: FindOptions): RegExp | null {
  if (query.trim() === "") return null;
  const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const body = wholeWord ? `(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])` : escaped;
  try {
    return new RegExp(body, caseSensitive ? "gu" : "giu");
  } catch {
    return null;
  }
}

/** The text nodes of one line of text (a paragraph, a list item), and the text they make together. */
export interface TextBlock {
  nodes: Text[];
  /** Where each node starts in `text`. */
  starts: number[];
  /** The text of all the nodes, with non-breaking spaces as spaces so a typed space finds them. */
  text: string;
}

function blockOf(nodes: Text[]): TextBlock {
  const starts: number[] = [];
  let text = "";
  for (const node of nodes) {
    starts.push(text.length);
    text += node.data;
  }
  return { nodes, starts, text: text.replace(/\u00a0/g, " ") };
}

function searchable(element: Element, root: Element, seen: Map<Element, boolean>): boolean {
  const known = seen.get(element);
  if (known !== undefined) return known;
  const skipped = element.closest(SKIPPED);
  let ok = !skipped || !root.contains(skipped);
  // Text that is not drawn (display none, inside a closed details) is not found: it could not be shown.
  if (ok && typeof element.checkVisibility === "function") ok = element.checkVisibility({ checkVisibilityCSS: true });
  seen.set(element, ok);
  return ok;
}

/** Walks the text of a region and hands it over one line of text at a time. */
function* readBlocks(root: HTMLElement): Generator<TextBlock> {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const seen = new Map<Element, boolean>();
  let owner: Element | null = null;
  let nodes: Text[] = [];
  for (let node = walker.nextNode() as Text | null; node; node = walker.nextNode() as Text | null) {
    const element = node.parentElement;
    if (!element || node.data === "" || !searchable(element, root, seen)) continue;
    const line: Element = element.closest(BLOCKS) ?? root;
    if (line !== owner && nodes.length) {
      yield blockOf(nodes);
      nodes = [];
    }
    owner = line;
    nodes.push(node);
  }
  if (nodes.length) yield blockOf(nodes);
}

/**
 * The text of a region, read once and kept for the next query: typing "late", "laten", "latenc" does not walk the page three
 * times. It reads as far as it is asked to, so the first query does not wait for the whole document. Make a new one when the
 * region changes.
 */
export class BlockStore {
  readonly blocks: TextBlock[] = [];
  private done = false;
  private readonly source: Generator<TextBlock>;

  constructor(root: HTMLElement) {
    this.source = readBlocks(root);
  }

  /** The block at a place in the document, reading on to it if it has not been read yet; undefined past the end. */
  at(index: number): TextBlock | undefined {
    while (index >= this.blocks.length && !this.done) {
      const next = this.source.next();
      if (next.done) this.done = true;
      else this.blocks.push(next.value);
    }
    return this.blocks[index];
  }
}

/** The part of a match that lies in one text node. */
export interface Piece {
  node: Text;
  from: number;
  to: number;
}

/**
 * One match: where it lies in the text nodes, and, when the search was asked for them, a range over it for painting with the CSS
 * Custom Highlight API and for scrolling. Wrapping matches in marks needs no range, and a range is a liability there: every one is
 * live, so every node that is split or moved has to update all of them.
 */
export interface FoundMatch {
  pieces: Piece[];
  range: Range | null;
}

/** The index of the last text node that starts before the offset (or at it, when it is the start of a match). */
function nodeAt(block: TextBlock, offset: number, atEnd: boolean): number {
  let low = 0;
  let high = block.starts.length - 1;
  while (low < high) {
    const middle = (low + high + 1) >> 1;
    const start = block.starts[middle] ?? 0;
    if (atEnd ? start < offset : start <= offset) low = middle;
    else high = middle - 1;
  }
  return low;
}

function matchOf(block: TextBlock, start: number, end: number, ranges: boolean): FoundMatch {
  const first = nodeAt(block, start, false);
  const last = nodeAt(block, end, true);
  const pieces: Piece[] = [];
  for (let at = first; at <= last; at += 1) {
    const node = block.nodes[at] as Text;
    const base = block.starts[at] ?? 0;
    pieces.push({ node, from: Math.max(start - base, 0), to: Math.min(end - base, node.length) });
  }
  if (!ranges) return { pieces, range: null };
  const range = document.createRange();
  const head = pieces[0] as Piece;
  const tail = pieces[pieces.length - 1] as Piece;
  range.setStart(head.node, head.from);
  range.setEnd(tail.node, tail.to);
  return { pieces, range };
}

/** Waits for the browser to be idle, and for a moment in browsers that cannot say. */
export function idle(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestIdleCallback === "function") requestIdleCallback(() => resolve(), { timeout: 150 });
    else setTimeout(resolve, 16);
  });
}

/** The longest a slice works before it gives the page back, in milliseconds. */
const SLICE_MS = 10;

export interface Batch {
  /** The matches found since the last batch, in document order. */
  matches: FoundMatch[];
  /** The search has looked at everything, or reached the limit. */
  done: boolean;
  /** It stopped at the limit. */
  capped: boolean;
}

export interface FindAllOptions {
  /** The most matches to hand over. Default `MAX_MATCHES`. */
  limit?: number;
  /** Give each match a live range, for painting with the Highlight API. Leave it off when the matches are wrapped in marks. Default true. */
  ranges?: boolean;
}

/**
 * Looks for a pattern in the text of a region and hands the matches over in batches, in document order. Each slice of work is a
 * few milliseconds and then waits for the browser to be idle, so typing, scrolling and clicking never wait for a search of a
 * log of a hundred thousand lines. `stale` says the query has moved on: the search then stops at once.
 */
export async function* findAll(store: BlockStore, pattern: RegExp, stale: () => boolean, { limit = MAX_MATCHES, ranges = true }: FindAllOptions = {}): AsyncGenerator<Batch> {
  let batch: FoundMatch[] = [];
  let total = 0;
  let started = performance.now();
  for (let index = 0; ; index += 1) {
    const block = store.at(index);
    if (!block) break;
    pattern.lastIndex = 0;
    for (let found = pattern.exec(block.text); found; found = pattern.exec(block.text)) {
      if (found[0] === "") {
        pattern.lastIndex += 1;
        continue;
      }
      batch.push(matchOf(block, found.index, found.index + found[0].length, ranges));
      total += 1;
      if (total >= limit) {
        yield { matches: batch, done: true, capped: true };
        return;
      }
    }
    if (performance.now() - started > SLICE_MS) {
      yield { matches: batch, done: false, capped: false };
      batch = [];
      await idle();
      if (stale()) return;
      started = performance.now();
    }
  }
  yield { matches: batch, done: true, capped: false };
}

/** A place in the document, kept so the next search can start from where the last one was. */
export interface Anchor {
  node: Node;
  offset: number;
}

/**
 * Whether a match starts at the anchor or after it, or contains it: the one to continue with when the query grows. It is read from the
 * pieces of the match, not from a range, so it holds for matches that were found without one.
 */
export function isFrom(match: FoundMatch, anchor: Anchor): boolean {
  const tail = match.pieces[match.pieces.length - 1];
  if (!tail) return true;
  if (tail.node === anchor.node) return anchor.offset <= tail.to;
  const where = anchor.node.compareDocumentPosition(tail.node);
  // An anchor that is no longer in the document cannot be compared: the search starts from the first match.
  if (where & Node.DOCUMENT_POSITION_DISCONNECTED) return true;
  return (where & Node.DOCUMENT_POSITION_FOLLOWING) !== 0;
}

/** The index of the first match that is `isFrom` the anchor, or -1 when there is none. The matches are in document order, so it is a bisection. */
export function findFrom(matches: readonly FoundMatch[], anchor: Anchor): number {
  let low = 0;
  let high = matches.length;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (isFrom(matches[middle] as FoundMatch, anchor)) high = middle;
    else low = middle + 1;
  }
  return low < matches.length ? low : -1;
}

/* ---- painting with the CSS Custom Highlight API ---- */

/** Whether the browser can paint a range without touching the page's elements. */
export function canHighlight(): boolean {
  return typeof CSS !== "undefined" && "highlights" in CSS && typeof Highlight !== "undefined";
}

/**
 * Adds the rules that paint the two highlights of one bar: every match in a soft tone of the text colour, the current one in the
 * inverted colours. They are written into a constructable stylesheet, which a strict Content Security Policy does not block the
 * way it blocks a style element, and they use the page's own tokens, so both themes work. Returns the function that takes them out.
 */
export function addHighlightStyles(all: string, current: string): () => void {
  if (typeof CSSStyleSheet === "undefined" || !("adoptedStyleSheets" in document)) return () => {};
  const sheet = new CSSStyleSheet();
  sheet.replaceSync(
    [
      `::highlight(${all}) { background-color: color-mix(in oklab, var(--foreground, CanvasText) 20%, transparent); color: inherit; }`,
      `::highlight(${current}) { background-color: var(--foreground, CanvasText); color: var(--background, Canvas); }`,
      `@media (forced-colors: active) { ::highlight(${all}) { background-color: Mark; color: MarkText; } ::highlight(${current}) { background-color: Highlight; color: HighlightText; } }`,
    ].join("\n"),
  );
  document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
  return () => {
    document.adoptedStyleSheets = document.adoptedStyleSheets.filter((other) => other !== sheet);
  };
}

/* ---- painting with wrapper marks ---- */

/**
 * The most matches that are wrapped in marks at one time. Wrapping is a few DOM changes for each match, so wrapping every match of a
 * log with ten thousand lines on every key press would hold the page for seconds; the ones around the current match are marked, and
 * the marks move along when the current match does. The count always covers every match.
 */
export const MAX_MARKED = 500;

/** What wrapping changed, so it can be undone exactly. */
export interface Wrapped {
  /** The marks of each match that was wrapped, by the index of the match. */
  marks: Map<number, HTMLElement[]>;
  /** The text nodes that were split, with what they said before. */
  originals: Map<Text, string>;
  /** The text nodes the splitting made. */
  created: Text[];
}

/**
 * Wraps the matches from `start` up to (not including) `end` in a `<mark>` each, from the last to the first so the offsets of the ones
 * before stay true. A match across several text nodes gets a mark in each. Undo it with `unwrap` before wrapping any other matches:
 * the offsets of the others are those of the text as it was.
 */
export function wrap(matches: readonly FoundMatch[], start = 0, end = matches.length): Wrapped {
  const wrapped: Wrapped = { marks: new Map(), originals: new Map(), created: [] };
  for (let at = Math.min(end, matches.length) - 1; at >= Math.max(start, 0); at -= 1) {
    const marks: HTMLElement[] = [];
    const pieces = (matches[at] as FoundMatch).pieces;
    for (let piece = pieces.length - 1; piece >= 0; piece -= 1) {
      const { node, from, to } = pieces[piece] as Piece;
      if (!node.isConnected) continue;
      if (!wrapped.originals.has(node)) wrapped.originals.set(node, node.data);
      if (to < node.length) wrapped.created.push(node.splitText(to));
      const middle = from > 0 ? node.splitText(from) : node;
      if (from > 0) wrapped.created.push(middle);
      const mark = document.createElement("mark");
      mark.setAttribute("data-rhs-find", "");
      mark.className = MARK_CLASS;
      middle.parentNode?.insertBefore(mark, middle);
      mark.appendChild(middle);
      marks.unshift(mark);
    }
    wrapped.marks.set(at, marks);
  }
  return wrapped;
}

/** Takes the marks out and puts the text back the way it was: the same nodes, with the same words, in the same places. */
export function unwrap(wrapped: Wrapped): void {
  for (const group of wrapped.marks.values()) {
    for (const mark of group) {
      const parent = mark.parentNode;
      if (!parent) continue;
      while (mark.firstChild) parent.insertBefore(mark.firstChild, mark);
      parent.removeChild(mark);
    }
  }
  for (const node of wrapped.created) node.remove();
  for (const [node, data] of wrapped.originals) node.data = data;
}

/* ---- scrolling ---- */

function scrollable(element: Element): boolean {
  const style = getComputedStyle(element);
  return /(auto|scroll|overlay)/.test(style.overflowY + style.overflowX) && (element.scrollHeight > element.clientHeight || element.scrollWidth > element.clientWidth);
}

/**
 * Scrolls whatever has to scroll so the match is inside its container with room to spare: it is not left at the very edge, or
 * under the find bar. `measure` gives the match's rectangle and is read again after each container has moved. Nothing moves
 * when it is already comfortably in view. The scrolling is instant, so stepping through matches with Enter keeps up with the fingers.
 */
export function scrollIntoMargin(measure: () => DOMRect, from: Element | null, margin: number): void {
  for (let element = from; element && element !== document.documentElement; element = element.parentElement) {
    if (!scrollable(element)) continue;
    const rect = measure();
    const box = element.getBoundingClientRect();
    const room = Math.min(margin, box.height / 4);
    const above = rect.top - (box.top + room);
    const below = rect.bottom - (box.bottom - room);
    const left = rect.left - (box.left + room);
    const right = rect.right - (box.right - room);
    const top = above < 0 ? above : below > 0 ? Math.min(below, above) : 0;
    const side = left < 0 ? left : right > 0 ? Math.min(right, left) : 0;
    if (top || side) element.scrollBy({ top, left: side, behavior: "instant" });
  }
  const rect = measure();
  const room = Math.min(margin, window.innerHeight / 4);
  const top = rect.top < room ? rect.top - room : rect.bottom > window.innerHeight - room ? Math.min(rect.bottom - (window.innerHeight - room), rect.top - room) : 0;
  if (top) window.scrollBy({ top, behavior: "instant" });
}
